const pool = require("../db");

async function setup() {
  if (!process.env.DATABASE_URL) {
    throw new Error("Перед запуском задайте DATABASE_URL.");
  }

  await pool.query(`
    CREATE TABLE IF NOT EXISTS "Products" (
      "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
      "Name" varchar(200) NOT NULL,
      "Category" varchar(100) NOT NULL,
      "Price" numeric(18, 2) NOT NULL,
      "IsAvailable" boolean NOT NULL DEFAULT true,
      "CreatedAt" timestamp with time zone NOT NULL DEFAULT NOW(),
      "Description" varchar(500) NOT NULL DEFAULT ''
    )
  `);

  const countResult = await pool.query('SELECT COUNT(*)::int AS count FROM "Products"');

  if (countResult.rows[0].count === 0) {
    await pool.query(`
      INSERT INTO "Products"
        ("Name", "Category", "Price", "IsAvailable", "Description")
      VALUES
        ('Ноутбук', 'Компьютеры', 2500, true, 'Ноутбук для работы и учёбы'),
        ('Мышь', 'Аксессуары', 80, true, 'Беспроводная мышь'),
        ('Клавиатура', 'Аксессуары', 150, true, 'Механическая клавиатура'),
        ('Монитор', 'Компьютеры', 720, true, 'Монитор 27 дюймов'),
        ('Наушники', 'Аудио', 210, false, 'Беспроводные наушники')
    `);
  }

  const result = await pool.query('SELECT COUNT(*)::int AS count FROM "Products"');
  console.log(`Таблица Products готова. Записей: ${result.rows[0].count}`);
}

setup()
  .catch((error) => {
    console.error("Ошибка подготовки PostgreSQL:", error.message);
    process.exitCode = 1;
  })
  .finally(async () => {
    await pool.end();
  });
